INSERT INTO "knowledge"."route_version" (route_id, number, content, content_hash, cases) VALUES
  ('ie-critical-skills', 4, '{"schemaVersion":1,"routeId":"ie-critical-skills","number":4,"corrects":3,"title":"Critical Skills Employment Permit for Ireland: a 2-year job offer in a critical skills occupation paying at least €40,904 a year, or any eligible job paying €68,911","country":"IE","tags":["work","temporary-residence"],"effectiveFrom":"2026-06-12","status":"open","currency":"EUR","leapDayBirthday":"unsettled","sources":[{"id":"ep-act-foreign-national","url":"https://www.irishstatutebook.ie/eli/2024/act/17/section/7/enacted/en/html","title":"Employment Permits Act 2024, s. 7(1): a foreign national shall not be in employment in the State except in accordance with an employment permit","kind":"official","verifiedAt":"2026-11-20"},{"id":"ep-act-eu-treaty-rights","url":"https://www.irishstatutebook.ie/eli/2024/act/17/section/8/enacted/en/html","title":"Employment Permits Act 2024, s. 8(1)(e): section 7 does not apply to a foreign national entitled to enter and work in the State under the treaties governing the European Union","kind":"official","verifiedAt":"2026-11-20"},{"id":"immigration-act-1999-non-national","url":"https://www.irishstatutebook.ie/eli/1999/act/22/section/1/enacted/en/html","title":"Immigration Act 1999, s. 1(1): a non-national is an alien under the Aliens Act 1935, other than an alien whom an order under s. 10 of that Act exempts from all of it","kind":"official","verifiedAt":"2026-11-20"},{"id":"aliens-exemption-order-1999","url":"https://www.irishstatutebook.ie/eli/1999/si/97/made/en/html","title":"Aliens (Exemption) Order 1999 (S.I. No. 97 of 1999), art. 3: every citizen of the United Kingdom is exempted from all the provisions of the Aliens Act 1935","kind":"official","verifiedAt":"2026-11-20"},{"id":"dete-who-needs-a-permit","url":"https://enterprise.gov.ie/en/what-we-do/workplace-and-skills/employment-permits/employment-permit-eligibility/who-needs-an-employment-permit-/","title":"Department of Enterprise, Tourism and Employment: non-EEA nationals need an employment permit; Swiss nationals work in Ireland without one under the 2001 Act on free movement with Switzerland","kind":"official","verifiedAt":"2026-11-20"},{"id":"ep-act-csep","url":"https://www.irishstatutebook.ie/eli/2024/act/17/section/22/enacted/en/html","title":"Employment Permits Act 2024, s. 22(1): no permit unless 50 per cent or more of the employees are nationals of the EEA, Switzerland or the United Kingdom, with exceptions","kind":"official","verifiedAt":"2026-11-20"},{"id":"ep-regs-csep","url":"https://www.irishstatutebook.ie/eli/2024/si/444/made/en/html","title":"Employment Permits Regulations 2024 (S.I. No. 444 of 2024), regs. 28 and 29: a minimum period of employment of 2 years and a minimum of 20 hours of work each week","kind":"official","verifiedAt":"2026-11-20"},{"id":"ep-regs-csep-qualification","url":"https://www.irishstatutebook.ie/eli/2024/si/444/made/en/html","title":"Employment Permits Regulations 2024 (S.I. No. 444 of 2024), reg. 27: a relevant third level degree; for a nurse, midwife or radiographer, one their registration board accepts","kind":"official","verifiedAt":"2026-11-20"},{"id":"ep-regs-mar-2026","url":"https://www.irishstatutebook.ie/eli/2025/si/643/made/en/html","title":"S.I. No. 643 of 2025, regs. 2, 4 to 7 and 21 (Schedule 8, Part 1), from 1 March 2026: €40,904, €36,848 with a level 8 degree of the last 12 months, €68,911, hourly rates, public sector pay agreements","kind":"official","verifiedAt":"2026-11-20"},{"id":"csol-schedule-3-may-2026","url":"https://www.irishstatutebook.ie/eli/2026/si/213/made/en/html","title":"S.I. No. 213 of 2026, reg. 4, made 13 May 2026: a new Schedule 3, the critical skills occupations, including ICT professionals in SOC 2133 to 2139 such as software developers","kind":"official","verifiedAt":"2026-11-20"},{"id":"csol-schedule-3-october-2026","url":"https://www.irishstatutebook.ie/eli/2026/si/558/made/en/html","title":"S.I. No. 558 of 2026, regs. 6 and 7, made 28 October 2026: Schedule 3 and the ineligible list in Schedule 4 replaced again; ICT professionals in SOC 2133 to 2139 stay on Schedule 3","kind":"official","verifiedAt":"2026-11-20"},{"id":"dete-csep","url":"https://enterprise.gov.ie/en/what-we-do/workplace-and-skills/employment-permits/permit-types/critical-skills-employment-permit/","title":"Department of Enterprise, Tourism and Employment, Critical Skills Employment Permit: €40,904, €36,848, €68,911, what counts as pay, 2-year job offer, 50% rule, immediate family reunification","kind":"official","verifiedAt":"2026-11-20"},{"id":"frp-nuclear-family","url":"https://www.irishimmigration.ie/wp-content/uploads/2026/06/Family-Reunification-Policy-12-June-2026.pdf","title":"Policy Document on Non-EEA Family Reunification (12 June 2026), paras. 1.5.1, 6.3 and 10.8: a Critical Skills Employment Permit holder''s spouse, partner and minor children may come on arrival","kind":"official","verifiedAt":"2026-11-20"},{"id":"frp-spouse","url":"https://www.irishimmigration.ie/wp-content/uploads/2026/06/Family-Reunification-Policy-12-June-2026.pdf","title":"Family Reunification Policy, paras. 7.5, 7.10 and 7.11: a spouse or civil partner 18 or over at application; a recognised civil partnership counts as marriage; 5 years before a new spouse","kind":"official","verifiedAt":"2026-11-20"},{"id":"frp-de-facto-partner","url":"https://www.irishimmigration.ie/wp-content/uploads/2026/06/Family-Reunification-Policy-12-June-2026.pdf","title":"Family Reunification Policy, glossary and paras. 7.12 to 7.13: a de facto partner 18 or over, in a relationship akin to marriage with at least 2 years of cohabitation before applying","kind":"official","verifiedAt":"2026-11-20"},{"id":"frp-children","url":"https://www.irishimmigration.ie/wp-content/uploads/2026/06/Family-Reunification-Policy-12-June-2026.pdf","title":"Family Reunification Policy, paras. 7.21, 7.22, 7.24, 7.26 and 8.2: biological, adopted or step-children, unmarried and under 18; stepchildren must be full-time members of the household","kind":"official","verifiedAt":"2026-11-20"},{"id":"frp-adult-relatives","url":"https://www.irishimmigration.ie/wp-content/uploads/2026/06/Family-Reunification-Policy-12-June-2026.pdf","title":"Family Reunification Policy, paras. 1.5, 6.3, 7.23, 8.3, 10.17, 10.19 and 10.21, Appendix D: dependent parents and adult children after 2 years, higher dependency and income thresholds","kind":"official","verifiedAt":"2026-11-20"},{"id":"frp-housing","url":"https://www.irishimmigration.ie/wp-content/uploads/2026/06/Family-Reunification-Policy-12-June-2026.pdf","title":"Family Reunification Policy, para. 9.4: a sponsor of any category must not live in homeless, emergency, IPAS, social or local authority housing","kind":"official","verifiedAt":"2026-11-20"},{"id":"isd-family-reunification-june-2026","url":"https://www.irishimmigration.ie/amendments-to-policy-on-non-eea-family-reunification/","title":"Immigration Service Delivery: amendments to the non-EEA Family Reunification Policy take effect from 12 June 2026","kind":"official","verifiedAt":"2026-11-20"},{"id":"isd-join-family","url":"https://www.irishimmigration.ie/coming-to-join-family-in-ireland/joining-a-non-eea-non-swiss-national/join-non-eea-family-member/","title":"Immigration Service Delivery, Join non EEA family member: a Category B sponsor, such as a Critical Skills Employment Permit holder, is joined at once by the nuclear family, by others after 2 years","kind":"official","verifiedAt":"2026-11-20"},{"id":"ep-regs-fees","url":"https://www.irishstatutebook.ie/eli/2024/si/444/made/en/html","title":"S.I. No. 444 of 2024, reg. 7, Schedule 1: €1,000 for a critical skills employment permit; no fee for a registered charity or an EEA, Swiss or UK national''s spouse or civil partner; 90% back on refusal","kind":"official","verifiedAt":"2026-11-20"},{"id":"dete-fees","url":"https://enterprise.gov.ie/en/what-we-do/workplace-and-skills/employment-permits/fees/","title":"Department of Enterprise, Tourism and Employment, Fees for Employment Permits: €1,000 for a Critical Skills Employment Permit of up to 24 months","kind":"official","verifiedAt":"2026-11-20"},{"id":"registration-fee","url":"https://www.irishstatutebook.ie/eli/2025/si/421/made/en/html","title":"Immigration Act 2004 (Registration Certificate Fee) Regulations 2025 (S.I. No. 421 of 2025), regs. 3 and 4: €300 for a registration certificate, waived for a person under the age of 18 years","kind":"official","verifiedAt":"2026-11-20"},{"id":"dete-stamp-4","url":"https://enterprise.gov.ie/en/what-we-do/workplace-and-skills/employment-permits/permit-types/critical-skills-employment-permit/","title":"Department of Enterprise, Tourism and Employment, Critical Skills Employment Permit, renewals: a holder can apply for a Stamp 4 permission, granted for 2 years, then renewable","kind":"official","verifiedAt":"2026-11-20"},{"id":"isd-stamp-4","url":"https://www.irishimmigration.ie/registering-your-immigration-permission/how-to-renew-your-current-permission/information-on-stamp-4-upgrades/","title":"Immigration Service Delivery, Stamp 4 upgrades: after 21 months of employment on a Critical Skills Employment Permit, a Stamp 4 renewable every 2 years","kind":"official","verifiedAt":"2026-11-20"}],"countries":{"id":"countries","number":1},"formerCountries":{"id":"former-countries","number":1},"officialDomains":[{"id":"ie","number":1}],"countrySets":[{"id":"eu-free-movement","number":2}],"requirements":[{"id":"not-eu-eea-or-swiss-citizen","title":"Not a citizen of Ireland, another EU or EEA state or Switzerland: they work in Ireland without an employment permit","expression":{"op":"not","operand":{"op":"intersects","list":{"op":"fact","key":"principal.citizenships"},"set":{"op":"set","id":"eu-free-movement"}}},"sources":["ep-act-foreign-national","ep-act-eu-treaty-rights","dete-who-needs-a-permit"]},{"id":"not-british-citizen","title":"Not a citizen of the United Kingdom: exempt from the Aliens Act 1935, a British citizen is no non-national and needs no employment permit","expression":{"op":"not","operand":{"op":"intersects","list":{"op":"fact","key":"principal.citizenships"},"set":{"op":"tokens","values":["GB"]}}},"sources":["ep-act-foreign-national","immigration-act-1999-non-national","aliens-exemption-order-1999"]}],"assessments":[{"id":"job-offer","title":"A job offer of at least 2 years and at least 20 hours of work each week","evidence":["principal.monthlyActiveIncome"],"sources":["ep-regs-csep","dete-csep"]},{"id":"employer-staff","title":"A bona fide employer trading in Ireland and registered with the Revenue Commissioners, at least half of whose employees are EEA, Swiss or UK nationals, save the exceptions of the act","evidence":["principal.monthlyActiveIncome"],"sources":["ep-act-csep","dete-csep"]},{"id":"critical-skills-occupation","title":"For the lower pay thresholds, a job in a critical skills occupation listed in Schedule 3 to the Employment Permits Regulations","evidence":["principal.educationLevel"],"sources":["csol-schedule-3-may-2026","csol-schedule-3-october-2026"]},{"id":"pay","title":"Pay of at least €40,904 a year and €20.17 an hour in a critical skills occupation, or €68,911 and €33.98 in any other eligible job; only basic salary and health insurance count, not bonuses","evidence":["principal.monthlyActiveIncome"],"sources":["ep-regs-mar-2026","dete-csep"]},{"id":"pay-recent-graduate","title":"Critical skills occupation, not a nurse, midwife or radiographer: €36,848 a year and €18.17 an hour are enough with a degree at level 8 or higher, or equivalent, from the 12 months before applying","evidence":["principal.monthlyActiveIncome","principal.educationLevel"],"sources":["ep-regs-mar-2026"]},{"id":"pay-public-sector-agreement","title":"A critical skills job bound by a public sector pay agreement, or by a Workplace Relations Commission agreement linked to one, needs that agreement''s pay instead of the €40,904 or €36,848 threshold","evidence":["principal.monthlyActiveIncome"],"sources":["ep-regs-mar-2026","dete-csep"]},{"id":"qualification","title":"A relevant third level degree (a nurse, midwife or radiographer: a degree or diploma their registration board accepts); for a job paying €68,911 or more, a relevant degree or the experience","evidence":["principal.educationLevel"],"sources":["ep-regs-csep-qualification","ep-regs-mar-2026","dete-csep"]},{"id":"dependent-adult-relatives","title":"Dependent parent or adult child, after 2 years in Ireland: Irish gross income over €96,929 in each of the 3 prior years for one adult, €130,985 for two (2026); Stamp 0 first; private health insurance","evidence":["principal.monthlyActiveIncome"],"sources":["frp-adult-relatives","isd-join-family"]},{"id":"family-housing","title":"For the family to join: the principal not living in homeless, emergency or IPAS accommodation, or in social or local authority housing; social housing support such as HAP may also fail","evidence":["principal.monthlyActiveIncome"],"sources":["frp-housing"]}],"dependents":[{"id":"spouse","title":"Spouse or civil partner aged 18 or over; after a divorce from a spouse who joined the principal, a new spouse only 5 years after that first permission (not checked)","path":["spouse"],"condition":{"op":"gte","left":{"op":"fact","key":"person.ageYears"},"right":{"op":"int","value":18}},"sources":["frp-nuclear-family","frp-spouse","isd-family-reunification-june-2026","isd-join-family"]},{"id":"partner","title":"De facto partner aged 18 or over, after 2 years together; a shorter relationship, which may be a civil partnership: possible","path":["partner"],"condition":{"op":"all","operands":[{"op":"gte","left":{"op":"fact","key":"person.ageYears"},"right":{"op":"int","value":18}},{"op":"any","operands":[{"op":"since","date":{"op":"fact","key":"edge.start"},"duration":"P2Y"},{"op":"unmodeled"}]}]},"sources":["frp-nuclear-family","frp-spouse","frp-de-facto-partner","isd-join-family"]},{"id":"children","title":"Children under 18 and unmarried (with a partner: possible), biological or adopted (Irish recognition not checked); a child over 18 dependent for a serious medical or psychological condition: possible","path":["child"],"condition":{"op":"any","operands":[{"op":"all","operands":[{"op":"not","operand":{"op":"fact","key":"person.hasSpouse"}},{"op":"lt","left":{"op":"fact","key":"person.ageYears"},"right":{"op":"int","value":18}},{"op":"any","operands":[{"op":"not","operand":{"op":"fact","key":"person.hasPartner"}},{"op":"unmodeled"}]}]},{"op":"all","operands":[{"op":"gte","left":{"op":"fact","key":"person.ageYears"},"right":{"op":"int","value":18}},{"op":"fact","key":"person.dependsOnPrincipal"},{"op":"unmodeled"}]}]},"sources":["frp-nuclear-family","frp-children","frp-adult-relatives","isd-join-family"]},{"id":"spouse-children","title":"The spouse or civil partner''s children as stepchildren, on the same terms as the principal''s children; living full time in the household is not checked","path":["spouse","child"],"condition":{"op":"any","operands":[{"op":"all","operands":[{"op":"not","operand":{"op":"fact","key":"person.hasSpouse"}},{"op":"lt","left":{"op":"fact","key":"person.ageYears"},"right":{"op":"int","value":18}},{"op":"any","operands":[{"op":"not","operand":{"op":"fact","key":"person.hasPartner"}},{"op":"unmodeled"}]}]},{"op":"all","operands":[{"op":"gte","left":{"op":"fact","key":"person.ageYears"},"right":{"op":"int","value":18}},{"op":"fact","key":"person.dependsOnPrincipal"},{"op":"unmodeled"}]}]},"sources":["frp-nuclear-family","frp-children","frp-adult-relatives"]},{"id":"partner-children","title":"The de facto partner''s children, on the terms of the principal''s children: possible, as stepchildren living full time in the household; the Policy does not say a partner''s child is a stepchild","path":["partner","child"],"condition":{"op":"all","operands":[{"op":"any","operands":[{"op":"all","operands":[{"op":"not","operand":{"op":"fact","key":"person.hasSpouse"}},{"op":"lt","left":{"op":"fact","key":"person.ageYears"},"right":{"op":"int","value":18}},{"op":"any","operands":[{"op":"not","operand":{"op":"fact","key":"person.hasPartner"}},{"op":"unmodeled"}]}]},{"op":"all","operands":[{"op":"gte","left":{"op":"fact","key":"person.ageYears"},"right":{"op":"int","value":18}},{"op":"fact","key":"person.dependsOnPrincipal"},{"op":"unmodeled"}]}]},{"op":"unmodeled"}]},"sources":["frp-nuclear-family","frp-children","frp-adult-relatives"]},{"id":"parents","title":"Parents who depend on the principal, without independent means: possible once the principal has 2 years in Ireland and Irish income in each of the 3 prior years (assessment)","path":["parent"],"condition":{"op":"all","operands":[{"op":"fact","key":"person.dependsOnPrincipal"},{"op":"unmodeled"}]},"sources":["frp-adult-relatives","isd-join-family"]}],"costs":[{"id":"application-fee","title":"Permit fee, paid by the worker, the employer or another; an employer may not recover it from the worker; 90% back on refusal or withdrawal; not checked: charity and EEA, Swiss or UK spouse waivers","kind":"fee","amount":{"op":"money","amount":100000,"currency":"EUR"},"appliesTo":"principal","sources":["ep-regs-fees","dete-fees","dete-csep"]},{"id":"registration-fee","title":"Fee for the registration certificate (IRP card) on registering the immigration permission, €300; the waivers in reg. 4 are not checked","kind":"fee","amount":{"op":"money","amount":30000,"currency":"EUR"},"appliesTo":"principal","sources":["registration-fee"]},{"id":"registration-fee-adult-dependant","title":"Fee for the registration certificate of each family member aged 18 or over, €300; waived for a person under the age of 18 years","kind":"fee","amount":{"op":"money","amount":30000,"currency":"EUR"},"appliesTo":"each_dependent","condition":{"op":"gte","left":{"op":"fact","key":"person.ageYears"},"right":{"op":"int","value":18}},"sources":["registration-fee"]}],"durations":[{"id":"permit","title":"Crit